# The pass for the DIAGNOSTIC copy of the lost-click probe, Upstream/tests/lost-click-probe.feature (not part of the suite: it is
# expected to fail, to show the report a lost click prints). Played on 2026-09-25 it failed one step earlier than intended:
# "tag 'btn:New colony' not found; known tags: no tags recorded this frame", the probe windows leaving Pickle no tag to click.
#
#   scripts/Run-PickleWsl.ps1 -Mod PickleTools -DepMap wsl-deps.lostclickprobe.map -Filter lost-click-probe.feature -PickleSrc <build>
#
# `path:` names a folder of this repository (relative to its root); the folder's own About.xml packageId must match.
nelim.pickletools.lostclickprobe   path:PickleTools/Upstream/tests/lost-click-probe/Mod
nelim.pickletools   path:PickleTools/Tests/Pickle/StandaloneBase/Mod
